  \*************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************/
/* Design System Semantic Tokens for Product UI */

:root,
.theme-studio-daylight {
  --color-canvas: #F7F8FC;
  --color-surface: #FCFCFF;
  --color-surface-subtle: #F0F1F7;
  --color-surface-brand: #F0EAFF;
  --color-surface-raised: #FFFFFF;
  --color-text: #2B2138;
  --color-text-muted: #6C6575;
  --color-border: #DDD8E5;
  --color-brand: #6430D7;
  --color-brand-hover: #5525BF;
  --color-brand-active: #47209F;
  --color-focus: #5B2CCB;
  --color-on-brand: #FFFFFF;

  --shadow-elevation: 0 18px 50px rgba(73, 52, 105, 0.10);
  --color-scheme: light;

  /* Theme-aware status surfaces. The --color-*-fg/bg/border set below is
     light-only; these resolve per theme so dark surfaces stay legible. */
  --color-danger-text: #B42318;
  --color-danger-surface: #FFF5F4;
  --color-danger-line: #FECDCA;
  --color-warning-text: #8A4B08;
  --color-warning-surface: #FFF8E7;
  --color-warning-line: #F7DBA7;
  --color-brand-line: rgba(100, 48, 215, 0.28);

  /* Scene stage: the frame around the 16:9 canvas, and the canvas itself. */
  --color-stage: #FFFFFF;
  --color-stage-canvas: #14101B;
}

.theme-focus-studio {
  --color-canvas: #18131F;
  --color-surface: #211A2B;
  --color-surface-subtle: #292035;
  --color-surface-brand: #342548;
  --color-surface-raised: #292035;
  --color-text: #F4F1F8;
  --color-text-muted: #BDB5C7;
  --color-border: #3A3046;
  --color-brand: #A883FF;
  --color-brand-hover: #B797FF;
  --color-brand-active: #976EFF;
  --color-focus: #A883FF;
  --color-on-brand: #1B1027;

  --shadow-elevation: 0 20px 60px rgba(8, 4, 14, 0.36);
  --color-scheme: dark;

  --color-danger-text: #FCA5A5;
  --color-danger-surface: rgba(180, 35, 24, 0.16);
  --color-danger-line: rgba(252, 165, 165, 0.30);
  --color-warning-text: #F5C15E;
  --color-warning-surface: rgba(138, 75, 8, 0.20);
  --color-warning-line: rgba(245, 193, 94, 0.28);
  --color-brand-line: rgba(168, 131, 255, 0.32);

  --color-stage: #1B1523;
  --color-stage-canvas: #0B0810;
}

/* Shared Brand & Semantic Tokens */
:root {
  --gradient-atmosphere: linear-gradient(135deg, #6F35E8 0%, #8B68EE 52%, #79A9E7 100%);

  --color-success-fg: #176B46;
  --color-success-bg: #EFFAF4;
  --color-success-border: #B7E4CA;

  --color-warning-fg: #8A4B08;
  --color-warning-bg: #FFF8E7;
  --color-warning-border: #F7DBA7;

  --color-error-fg: #B42318;
  --color-error-bg: #FFF5F4;
  --color-error-border: #FECDCA;

  --color-info-fg: #3159A6;
  --color-info-bg: #F0F5FF;
  --color-info-border: #B8D3FF;

  /* Shape system: cards use --radius-card, primary CTAs and pill-shaped
     controls use --radius-pill, every other control (secondary/tertiary/
     destructive buttons, form inputs, rounded icon buttons) uses
     --radius-control, and icon-only controls default to --radius-circle.
     See components/ui/button.module.css and icon-button.module.css. */
  --radius-card: 16px;
  --radius-control: 10px;
  --radius-pill: 9999px;
  --radius-circle: 50%;

  --motion-instant: 120ms;
  --motion-quick: 200ms;
  --motion-standard: 320ms;
  --motion-transform: 600ms;
  --motion-easing: cubic-bezier(0.16, 1, 0.3, 1);

  /* Geist Sans/Mono are self-hosted by the `geist` package through next/font;
     the --font-geist-* variables are set on <html> in app/layout.tsx. */
  --font-family-sans: var(--font-geist-sans), "Segoe UI", Arial, sans-serif;
  --font-family-mono: var(--font-geist-mono), "Cascadia Mono", Consolas, monospace;

  /* Type scale (docs/design.md 5.2). Each role is size / line-height. */
  --text-display: 700 56px/60px var(--font-family-sans);
  --text-page-title: 700 36px/42px var(--font-family-sans);
  --text-editor-title: 700 28px/34px var(--font-family-sans);
  --text-section-title: 600 24px/30px var(--font-family-sans);
  --text-subsection-title: 600 18px/24px var(--font-family-sans);
  --text-body: 400 16px/24px var(--font-family-sans);
  --text-control: 500 14px/20px var(--font-family-sans);
  --text-supporting: 400 13px/18px var(--font-family-sans);
}

/* Base Styles */
* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  background-color: var(--color-canvas);
  color: var(--color-text);
  font-family: var(--font-family-sans);
  -webkit-font-smoothing: antialiased;
  color-scheme: var(--color-scheme, light);
}

.tabular-nums {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum";
}

/* Focus Indicator Standards */
*:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

/* Scene preview transport.
   Styled globally because @avlp/scene-library is compiled by tsc and cannot
   consume CSS modules; the class names are namespaced with an sp- prefix. */

.sp-player {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
}

.sp-player > :first-child {
  flex: 1 1;
  min-height: 0;
}

.sp-transport {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background-color: var(--color-surface);
  border-top: 1px solid var(--color-border);
}

.sp-button {
  font: var(--text-supporting);
  font-weight: 500;
  min-width: 62px;
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--color-border);
  background-color: var(--color-surface-subtle);
  color: var(--color-text);
  cursor: pointer;
  white-space: nowrap;
  transition:
    background-color var(--motion-quick) var(--motion-easing),
    border-color var(--motion-quick) var(--motion-easing),
    color var(--motion-quick) var(--motion-easing),
    transform var(--motion-instant) var(--motion-easing);
}

.sp-button:hover {
  background-color: var(--color-surface-brand);
  border-color: var(--color-brand);
  color: var(--color-brand);
}

.sp-button:active {
  transform: scale(0.97);
}

/* The play/pause toggle is the primary control in the bar. */
.sp-button-primary {
  background-color: var(--color-brand);
  border-color: var(--color-brand);
  color: var(--color-on-brand);
  font-weight: 600;
}

.sp-button-primary:hover {
  background-color: var(--color-brand-hover);
  border-color: var(--color-brand-hover);
  color: var(--color-on-brand);
}

/* Seek track. The played portion is filled from --sp-progress, set by the
   player as the current frame advances. */
.sp-seek {
  flex: 1 1;
  min-width: 80px;
  height: 6px;
  -moz-appearance: none;
       appearance: none;
  -webkit-appearance: none;
  border-radius: var(--radius-pill);
  background-image: linear-gradient(
    to right,
    var(--color-brand) 0,
    var(--color-brand) var(--sp-progress, 0%),
    var(--color-border) var(--sp-progress, 0%),
    var(--color-border) 100%
  );
  cursor: pointer;
}

.sp-seek::-webkit-slider-thumb {
  appearance: none;
  -webkit-appearance: none;
  width: 14px;
  height: 14px;
  border-radius: var(--radius-circle);
  background-color: var(--color-brand);
  border: 2px solid var(--color-surface);
  cursor: pointer;
}

.sp-seek::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border-radius: var(--radius-circle);
  background-color: var(--color-brand);
  border: 2px solid var(--color-surface);
  cursor: pointer;
}

.sp-time {
  font: var(--text-supporting);
  font-family: var(--font-family-mono);
  font-feature-settings: "tnum";
  font-variant-numeric: tabular-nums;
  color: var(--color-text-muted);
  white-space: nowrap;
}

/* Full-lesson transport. The lesson player stacks two rows - the play
   controls above, the per-scene jump list below - so it wraps them in
   .sp-transport-stack instead of using .sp-transport on its own. */

.sp-transport-stack {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 14px;
  background-color: var(--color-surface);
  border-top: 1px solid var(--color-border);
}

.sp-transport-stack .sp-transport {
  padding: 0;
  background-color: transparent;
